def clean(df):
    df['Region'] = df['Region'].str.lower().replace({'west': 'West', 'south': 'South', 'wst': 'West', 'suoth': 'South'})
    df = df.dropna(subset=['Region'])
    df['Quantity'] = df['Quantity'].clip(lower=0)
    df['Price'] = df['Price'].str.replace('$', '').astype(float)
    return df

def answer(df):
    result = df.groupby('Region')['Quantity'].sum().to_dict()
    return result}
